// Value: protects=/students asks for attendance only with attendance.view AND sessions.view, balance with session_ledger.view, debt with payments.view,
// and hands the loaded metrics to StudentListPage;
// fails_when=attendance loads on attendance.view alone (the session-date window needs sessions.view), a column keys off the wrong permission,
// or metrics stop reaching the page (every cell falls back to "no permission");
// why_new=permission wiring lives only in the route; presentation tests pass metrics as props and the loader test passes flags directly;
// seam=none (loaders and StudentListPage mocked at module boundaries; returned element props inspected); no_claim=does not prove RLS or the real queries
import type { ComponentProps, ReactElement } from "react";
import { afterEach, describe, expect, it, vi } from "vitest";

import StudentsRoute from "@/app/(app)/students/page";
import type { StudentListPage } from "@/features/students/student-list-page";
import type { StudentDirectoryMetrics } from "@/features/students/student-directory-metrics";

const dependencies = vi.hoisted(() => ({
  getCachedDatabasePermissions: vi.fn(),
  getStudentDirectory: vi.fn(),
  getStudentDirectoryMetrics: vi.fn(),
  StudentListPage: vi.fn(() => null),
}));

vi.mock("@/lib/permissions/database-permissions", () => ({
  getCachedDatabasePermissions: dependencies.getCachedDatabasePermissions,
}));
vi.mock("@/features/students/data", () => ({
  getStudentDirectory: dependencies.getStudentDirectory,
  getStudentDirectoryMetrics: dependencies.getStudentDirectoryMetrics,
}));
vi.mock("@/features/students/student-list-page", () => ({ StudentListPage: dependencies.StudentListPage }));

const metrics: StudentDirectoryMetrics = {
  attendanceRate: { byStudentId: { "student-1": 71 }, status: "ready" },
  balanceSessions: { reason: "forbidden", status: "unavailable" },
  outstandingVnd: { byStudentId: {}, status: "ready" },
};

async function renderRoute(permissions: string[]) {
  dependencies.getCachedDatabasePermissions.mockResolvedValue({ ok: true, permissions });
  dependencies.getStudentDirectory.mockResolvedValue({ ok: true, students: [] });
  dependencies.getStudentDirectoryMetrics.mockResolvedValue(metrics);

  return (await StudentsRoute()) as ReactElement<ComponentProps<typeof StudentListPage>>;
}

afterEach(() => {
  vi.clearAllMocks();
});

describe("Students route metric permission wiring", () => {
  it("gates each metric column on its own view permissions and passes the loaded metrics to the page", async () => {
    await renderRoute(["students.view", "attendance.view", "session_ledger.view"]);
    expect(dependencies.getStudentDirectoryMetrics).toHaveBeenLastCalledWith({
      includeAttendance: false,
      includeBalance: true,
      includeDebt: false,
    });

    await renderRoute(["students.view", "sessions.view", "payments.view"]);
    expect(dependencies.getStudentDirectoryMetrics).toHaveBeenLastCalledWith({
      includeAttendance: false,
      includeBalance: false,
      includeDebt: true,
    });

    const element = await renderRoute(["students.view", "attendance.view", "sessions.view"]);
    expect(dependencies.getStudentDirectoryMetrics).toHaveBeenLastCalledWith({
      includeAttendance: true,
      includeBalance: false,
      includeDebt: false,
    });
    expect(element.type).toBe(dependencies.StudentListPage);
    expect(element.props.metrics).toBe(metrics);
  });
});
